func TestRenderExternalFileHeader(t *testing.T) {
	r, err := NewRenderer()
	if err != nil {
		t.Fatalf("NewRenderer() error = %v", err)
	}

	output, err := r.RenderExternalFileHeader(ExternalFileHeaderData{
		PackageName: "adminclient",
	})
	if err != nil {
		t.Fatalf("RenderExternalFileHeader() error = %v", err)
	}

	if output == "" {
		t.Error("RenderExternalFileHeader() returned empty string")
	}

	// Verify expected content is present.
	expectedContent := []string{
		"Code generated by protoc-gen-go-http-client",
		"package adminclient",
		"import",
	}
	for _, expected := range expectedContent {
		if !strings.Contains(output, expected) {
			t.Errorf("RenderExternalFileHeader() missing %q", expected)
		}
	}
}

