func TestRenderServiceClient(t *testing.T) {
	r, err := NewRenderer()
	if err != nil {
		t.Fatalf("NewRenderer() error = %v", err)
	}

	data := ServiceClientData{
		ClientName:       "AdminClient",
		ServiceInterface: "AdminService",
		ServicePath:      "kebabCaseServicePath(\"AdminService\")",
		Methods: []MethodData{
			{
				MethodName: "GetUser",
				InputType:  "GetUserRequest",
				OutputType: "GetUserResponse",
				ClientName: "AdminClient",
			},
		},
	}

	output, err := r.RenderServiceClient(data)
	if err != nil {
		t.Fatalf("RenderServiceClient() error = %v", err)
	}

	expectedContent := []string{
		"type AdminClient struct",
		"func NewAdminClient",
		"func (c *AdminClient) GetUser",
	}
	for _, expected := range expectedContent {
		if !strings.Contains(output, expected) {
			t.Errorf("RenderServiceClient() missing %q", expected)
		}
	}
}

func TestRenderCompoundClient(t *testing.T) {
	r, err := NewRenderer()
	if err != nil {
		t.Fatalf("NewRenderer() error = %v", err)
	}

	data := CompoundClientData{
		PackageName: "adminclient",
		Services: []ServiceFieldData{
			{
				FieldName:  "User",
				ClientName: "UserServiceClient",
			},
			{
				FieldName:  "Admin",
				ClientName: "AdminServiceClient",
			},
		},
	}

	output, err := r.RenderCompoundClient(data)
	if err != nil {
		t.Fatalf("RenderCompoundClient() error = %v", err)
	}

	expectedContent := []string{
		"type Client struct",
		"User *UserServiceClient",
		"Admin *AdminServiceClient",
		"func NewClient",
	}
	for _, expected := range expectedContent {
		if !strings.Contains(output, expected) {
			t.Errorf("RenderCompoundClient() missing %q", expected)
		}
	}
}

var updateGolden = flag.Bool("update", false, "rewrite the golden files in testdata from the current templates")

// Pins the complete output of every {{define}} block in templates.tmpl against
// testdata/<block>.golden. The generated Go clients are consumed by other
// modules, so any change to the emitted text, however small, must show up here
// as a reviewable golden diff. Run `go test ./internal/render -update` to accept
// an intended template change.
func TestRenderMatchesGoldenFiles(t *testing.T) {
	r, err := NewRenderer()
	if err != nil {
		t.Fatalf("NewRenderer() error = %v", err)
	}

	tests := []struct {
		block  string
		render func() (string, error)
	}{
		{
			block: "external_file_header",
			render: func() (string, error) {
				return r.RenderExternalFileHeader(ExternalFileHeaderData{PackageName: "adminclient"})
			},
		},
		{
			block: "file_header",
			render: func() (string, error) {
				return r.RenderFileHeader(FileHeaderData{SourcePath: "users.proto", PackageName: "usersv1"})
			},
		},
		{
			block:  "shared_helpers",
			render: r.RenderSharedHelpers,
		},
		{
			block: "service_client",
			render: func() (string, error) {
				return r.RenderServiceClient(ServiceClientData{
					ClientName:       "UserServiceClient",
					ServiceInterface: "usersv1.UserService",
					ServicePath:      `kebabCaseServicePath("UserService")`,
					Methods: []MethodData{
						{MethodName: "GetUser", InputType: "usersv1.GetUserRequest", OutputType: "usersv1.GetUserResponse", ClientName: "UserServiceClient"},
						{MethodName: "ListUsers", InputType: "commonv1.Empty", OutputType: "usersv1.ListUsersResponse", ClientName: "UserServiceClient"},
					},
				})
			},
		},
		{
			block: "compound_client",
			render: func() (string, error) {
				return r.RenderCompoundClient(CompoundClientData{
					PackageName: "adminclient",
					Services: []ServiceFieldData{
						{FieldName: "Admin", ClientName: "AdminServiceClient"},
						{FieldName: "User", ClientName: "UserServiceClient"},
					},
				})
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.block, func(t *testing.T) {
			got, err := tt.render()
			if err != nil {
				t.Fatalf("render %s: %v", tt.block, err)
			}

			goldenPath := filepath.Join("testdata", tt.block+".golden")
			if *updateGolden {
				if err := os.WriteFile(goldenPath, []byte(got), 0o644); err != nil {
					t.Fatalf("write %s: %v", goldenPath, err)
				}
			}

			want, err := os.ReadFile(goldenPath)
			if err != nil {
				t.Fatalf("read %s: %v", goldenPath, err)
			}
			if got != string(want) {
				t.Errorf("%s output differs from %s\n--- got ---\n%s\n--- want ---\n%s", tt.block, goldenPath, got, want)
			}
		})
	}
}
